<?php

/**
 * PANDI EPP registrar module for WHMCS
 *
 * Settings of the optional PowerDNS cron scripts (cron.php, expire-cron.php).
 * Do not edit this file: put the real values in config.local.php (see
 * config.local.php.example, not committed) or in environment variables of the
 * same name.
 *
 * Copyright (C) 2023-2026 PANDI (Pengelola Nama Domain Internet Indonesia) and contributors
 * SPDX-License-Identifier: GPL-3.0-or-later
 */

if (PHP_SAPI !== 'cli') {
    http_response_code(403);
    exit;
}

if (is_file(__DIR__ . '/config.local.php')) {
    require __DIR__ . '/config.local.php';
}

foreach ([
    // PowerDNS HTTP API, e.g. https://pdns.example.net:8081/api/v1
    'PANDIWHMCS_PDNS_URL' => '',
    'PANDIWHMCS_PDNS_API_KEY' => '',
    'PANDIWHMCS_PDNS_SERVER' => 'localhost',
    // address of the parking page for new domains without hosting
    'PANDIWHMCS_PARKING_IP' => '',
    // address of the "this domain has expired" page; it must say the domain
    // expired and how to renew it (ICANN ERRP)
    'PANDIWHMCS_EXPIRED_IP' => '',
    // nameservers of the parking zones
    'PANDIWHMCS_PARKING_NS1' => '',
    'PANDIWHMCS_PARKING_NS2' => '',
    // domains handled per batch
    'PANDIWHMCS_CRON_BATCH' => '50',
] as $pandiwhmcsName => $pandiwhmcsDefault) {
    if (!defined($pandiwhmcsName)) {
        $pandiwhmcsEnv = getenv($pandiwhmcsName);
        define($pandiwhmcsName, $pandiwhmcsEnv !== false && $pandiwhmcsEnv !== '' ? $pandiwhmcsEnv : $pandiwhmcsDefault);
    }
}
unset($pandiwhmcsName, $pandiwhmcsDefault, $pandiwhmcsEnv);
